package org.dpdns.gmm;
import static org.junit.Assert.*;
import android.content.Context;import android.view.*;import android.os.SystemClock;import org.json.*;import java.util.*;import java.util.concurrent.TimeUnit;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowLooper;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w640dp-h320dp-land-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class NativeRoster60DraftTest {
 final NativeHomePartyFeedbackTest helper=new NativeHomePartyFeedbackTest();
 @Before public void setup(){helper.isolate();helper.configure(NativeRoster60HumanPvpTest.SMALL);} @After public void restore(){helper.restore();}
 static class Api extends NativeRoster60HumanPvpTest.Api {
  boolean delayParty;Result party;
  Api(Context c){super(c);}
  @Override void call(String p,JSONObject b,Result cb){if(delayParty&&p.endsWith("pvp/party")){paths.add(p);writes.add(b);party=cb;}else super.call(p,b,cb);}
 }
 Api prepare(MainActivity h)throws Exception{helper.prepare(h);Api api=new Api(h);h.api=api;h.getSharedPreferences("roster60_human_queue",0).edit().clear().commit();h.openRosterPvp();h.rosterPvp.editParty();return api;}
 @Test public void idleDoesNotPollDimWriteOrLoseLocalDraft()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();Api api=prepare(h);NativeRoster60Pvp ui=h.rosterPvp;ui.moveSelected(0,3);List<String> draft=new ArrayList<>(ui.selected);int calls=api.paths.size();long replacements=ui.slotReplacements,states=ui.tileStateUpdates;ShadowLooper.idleMainLooper(12,TimeUnit.SECONDS);assertEquals(calls,api.paths.size());assertTrue(api.writes.isEmpty());assertEquals(draft,ui.selected);assertEquals(replacements,ui.slotReplacements);assertEquals(states,ui.tileStateUpdates);assertFalse(ui.normal.isEnabled());assertTrue(ui.save.isEnabled());for(int i=0;i<6;i++)assertEquals(1f,ui.slots.getChildAt(i).getAlpha(),0);ui.fetchOptions();assertEquals(draft,ui.selected);ui.pause();}}
 @Test public void latestOrderedDraftIsSavedOnceAndFailureRestoresEditing()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){
  MainActivity h=c.get();Api api=prepare(h);NativeRoster60Pvp ui=h.rosterPvp;ui.moveSelected(0,4);String expected=new JSONArray(ui.selected).toString();api.delayParty=true;
  ui.save.performClick();ui.save();assertEquals(1,api.writes.size());assertEquals(expected,api.writes.get(0).getJSONArray("ownedIds").toString());assertFalse(api.paths.contains("native/roster60/pvp/join"));
  api.party.done(null,"INVALID_PARTY");assertFalse(ui.busy);assertTrue(ui.editing);assertTrue(ui.save.isEnabled());assertFalse(ui.normal.isEnabled());assertEquals(expected,new JSONArray(ui.selected).toString());
  ui.save.performClick();assertEquals(2,api.writes.size());api.party.done(new JSONObject(),null);assertFalse(ui.editing);assertTrue(ui.normal.isEnabled());assertFalse(api.paths.contains("native/roster60/pvp/join"));
  ui.normal.performClick();assertEquals(3,api.writes.size());api.party.done(new JSONObject(),null);assertEquals(4,api.writes.size());assertEquals("normal",api.writes.get(3).getString("mode"));ui.join("normal");assertEquals(4,api.writes.size());ui.pause();
 }}
 @Test public void insertShiftsBothDirectionsWithoutSwapping(){List<String> ids=new ArrayList<>(Arrays.asList("a","b","c","d","e","f"));assertTrue(Roster60PartySlots.insert(ids,0,3));assertEquals(Arrays.asList("b","c","d","a","e","f"),ids);assertTrue(Roster60PartySlots.insert(ids,4,1));assertEquals(Arrays.asList("b","e","c","d","a","f"),ids);assertFalse(Roster60PartySlots.insert(ids,1,1));assertFalse(Roster60PartySlots.insert(ids,1,6));}
 static void touch(View view,int action,float x,float y){long now=SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(now,now,action,x,y,0);try{view.dispatchTouchEvent(e);}finally{e.recycle();}}
 @Test public void dragReleaseInsertsAndCancelDoesNotClickOrSend()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();Api api=prepare(h);NativeRoster60Pvp ui=h.rosterPvp;helper.layout(h,NativeRoster60HumanPvpTest.SMALL);Roster60PartySlots row=(Roster60PartySlots)ui.slots;float x=row.getChildAt(0).getX()+row.getChildAt(0).getWidth()/2f,y=row.getHeight()/2f,to=row.getChildAt(3).getX()+row.getChildAt(3).getWidth()/2f;List<String> before=new ArrayList<>(ui.selected);touch(row,MotionEvent.ACTION_DOWN,x,y);touch(row,MotionEvent.ACTION_MOVE,to,y);touch(row,MotionEvent.ACTION_CANCEL,to,y);assertEquals(before,ui.selected);touch(row,MotionEvent.ACTION_DOWN,x,y);touch(row,MotionEvent.ACTION_MOVE,to,y);touch(row,MotionEvent.ACTION_UP,to,y);assertEquals(Arrays.asList("owned1","owned2","owned3","owned0","owned4","owned5"),ui.selected);assertTrue(api.writes.isEmpty());ui.pause();}}
 @Test public void bothRowsShowEachOwnedCharactersLevel()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();prepare(h);NativeRoster60Pvp ui=h.rosterPvp;for(int i=0;i<ui.units.length();i++)ui.units.getJSONObject(i).put("level",i+7);ui.catalogueDirty=true;ui.drawParty();for(int i=0;i<6;i++)assertEquals("Lv. "+(i+7),((Roster60MemberTile)ui.slots.getChildAt(i)).role.getText().toString());for(int i=0;i<7;i++)assertEquals("Lv. "+(i+7),ui.ownedTiles.get("owned"+i).role.getText().toString());helper.layout(h,NativeRoster60HumanPvpTest.SMALL);helper.png(NativeHomePartyFeedbackTest.render(h.root),"formation-draft-levels-640x320.png");ui.pause();}}

 @Test public void candidatesSortByDescendingLevelWithStableTiesWithoutSortingParty()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();prepare(h);NativeRoster60Pvp ui=h.rosterPvp;List<String> party=new ArrayList<>(ui.selected);int[] levels={5,60,12,60,1,12,30};for(int i=0;i<levels.length;i++)ui.units.getJSONObject(i).put("level",levels[i]);ui.catalogueDirty=true;ui.drawParty();assertEquals(Arrays.asList("owned1","owned3","owned6","owned2","owned5","owned0","owned4"),new ArrayList<>(ui.ownedTiles.keySet()));assertEquals(party,ui.selected);ui.moveSelected(0,5);assertEquals("owned0",ui.selected.get(5));ui.drawParty();assertEquals("owned0",ui.selected.get(5));ui.pause();}}
 @Test public void liftedCardFollowsFingerHasShadowAndCancelRestoresEveryTransform()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();Api api=prepare(h);NativeRoster60Pvp ui=h.rosterPvp;helper.layout(h,NativeRoster60HumanPvpTest.SMALL);Roster60PartySlots row=(Roster60PartySlots)ui.slots;View card=row.getChildAt(0);float x=card.getX()+card.getWidth()/2f,y=row.getHeight()/2f,to=row.getChildAt(3).getX()+row.getChildAt(3).getWidth()/2f;List<String> before=new ArrayList<>(ui.selected);touch(row,MotionEvent.ACTION_DOWN,x,y);touch(row,MotionEvent.ACTION_MOVE,to,y+4);assertTrue(row.dragging);assertTrue(card.getScaleX()>1);assertTrue(card.getElevation()>0);assertEquals(to-x,card.getTranslationX(),.01f);assertEquals(4-row.lift,card.getTranslationY(),.01f);assertTrue(row.getChildAt(1).getTranslationX()<0);helper.png(NativeHomePartyFeedbackTest.render(h.root),"formation-card-lifted-640x320.png");touch(row,MotionEvent.ACTION_CANCEL,to,y+4);assertFalse(row.dragging);for(int i=0;i<6;i++){View v=row.getChildAt(i);assertEquals(1f,v.getScaleX(),0);assertEquals(1f,v.getScaleY(),0);assertEquals(0f,v.getTranslationX(),0);assertEquals(0f,v.getTranslationY(),0);assertEquals(0f,v.getElevation(),0);}ShadowLooper.idleMainLooper();assertEquals(before,ui.selected);assertTrue(api.writes.isEmpty());ui.pause();}}
 @Test public void accessibilityMovesWithoutDragAndVerticalGestureNeverClicks()throws Exception{try(ActivityController<MainActivity> c=helper.flow.start()){MainActivity h=c.get();Api api=prepare(h);NativeRoster60Pvp ui=h.rosterPvp;helper.layout(h,NativeRoster60HumanPvpTest.SMALL);Roster60PartySlots row=(Roster60PartySlots)ui.slots;assertTrue(((Roster60MemberTile)row.getChildAt(0)).action.performAccessibilityAction(Roster60PartySlots.MOVE_LATER,null));assertEquals(Arrays.asList("owned1","owned0","owned2","owned3","owned4","owned5"),ui.selected);helper.layout(h,NativeRoster60HumanPvpTest.SMALL);List<String> before=new ArrayList<>(ui.selected);View card=row.getChildAt(0);float x=card.getLeft()+card.getWidth()/2f,y=row.getHeight()/2f;touch(row,MotionEvent.ACTION_DOWN,x,y);touch(row,MotionEvent.ACTION_MOVE,x,y+row.slop+2);touch(row,MotionEvent.ACTION_UP,x,y+row.slop+2);ShadowLooper.idleMainLooper();assertEquals(before,ui.selected);assertTrue(api.writes.isEmpty());ui.pause();}}
}
